import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { Link, useNavigate, useLocation } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { toast } from 'sonner'
import { supabaseAuthService } from '@/integrations/supabase/auth'
import { ensureDevSuperadminSession } from '@/app/devAutoLogin'

const passwordSchema = z.object({
  email: z.string().email(),
  password: z.string().min(6),
})
const magicSchema = z.object({ email: z.string().email() })

type PwForm = z.infer<typeof passwordSchema>
type MagicForm = z.infer<typeof magicSchema>

export function LoginPage() {
  const { t } = useTranslation('auth')
  const navigate = useNavigate()
  const location = useLocation()
  const from = (location.state as { from?: { pathname: string } })?.from?.pathname ?? '/app/home'
  const [mode, setMode] = useState<'password' | 'magic'>('password')

  const pwForm = useForm<PwForm>({ resolver: zodResolver(passwordSchema) })
  const magicForm = useForm<MagicForm>({ resolver: zodResolver(magicSchema) })

  const onPasswordSubmit = async (data: PwForm) => {
    try {
      await supabaseAuthService.signInWithEmail(data.email, data.password)
      navigate(from, { replace: true })
    } catch (e) {
      toast.error((e as Error).message || t('errors.loginFailed'))
    }
  }

  const onMagicSubmit = async (data: MagicForm) => {
    try {
      await supabaseAuthService.signInWithMagicLink(data.email)
      toast.success('Magic link sent. Check your email.')
    } catch (e) {
      toast.error((e as Error).message || 'Failed to send magic link.')
    }
  }

  return (
    <div className="bg-surface rounded-2xl border border-border p-8 shadow-sm">
      <h1 className="text-xl font-semibold mb-1">{t('loginTitle')}</h1>
      <p className="text-sm text-muted-foreground mb-6">{t('loginSubtitle')}</p>

      <div className="flex gap-1 p-1 bg-muted rounded-lg mb-5">
        <button
          type="button"
          onClick={() => setMode('password')}
          className={`flex-1 text-xs py-1.5 rounded-md transition-colors ${mode === 'password' ? 'bg-surface text-foreground shadow-sm' : 'text-muted-foreground'}`}
        >
          Password
        </button>
        <button
          type="button"
          onClick={() => setMode('magic')}
          className={`flex-1 text-xs py-1.5 rounded-md transition-colors ${mode === 'magic' ? 'bg-surface text-foreground shadow-sm' : 'text-muted-foreground'}`}
        >
          Magic link
        </button>
      </div>

      {mode === 'password' ? (
        <form onSubmit={pwForm.handleSubmit(onPasswordSubmit)} className="flex flex-col gap-4">
          <div>
            <label className="text-sm font-medium block mb-1.5">{t('email')}</label>
            <input
              {...pwForm.register('email')}
              type="email"
              className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent transition-colors"
              placeholder="you@example.com"
            />
            {pwForm.formState.errors.email && <p className="text-xs text-danger mt-1">{pwForm.formState.errors.email.message}</p>}
          </div>
          <div>
            <label className="text-sm font-medium block mb-1.5">{t('password')}</label>
            <input
              {...pwForm.register('password')}
              type="password"
              className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent transition-colors"
            />
            {pwForm.formState.errors.password && <p className="text-xs text-danger mt-1">{pwForm.formState.errors.password.message}</p>}
          </div>

          <div className="flex justify-end">
            <Link to="/auth/forgot-password" className="text-xs text-accent hover:underline">
              {t('forgotPassword')}
            </Link>
          </div>

          <button
            type="submit"
            disabled={pwForm.formState.isSubmitting}
            className="w-full bg-accent text-accent-foreground rounded-lg py-2.5 text-sm font-medium hover:opacity-90 disabled:opacity-50 transition-opacity"
          >
            {pwForm.formState.isSubmitting ? '...' : t('login')}
          </button>
        </form>
      ) : (
        <form onSubmit={magicForm.handleSubmit(onMagicSubmit)} className="flex flex-col gap-4">
          <div>
            <label className="text-sm font-medium block mb-1.5">{t('email')}</label>
            <input
              {...magicForm.register('email')}
              type="email"
              className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent transition-colors"
              placeholder="you@example.com"
            />
            {magicForm.formState.errors.email && <p className="text-xs text-danger mt-1">{magicForm.formState.errors.email.message}</p>}
          </div>
          <button
            type="submit"
            disabled={magicForm.formState.isSubmitting}
            className="w-full bg-accent text-accent-foreground rounded-lg py-2.5 text-sm font-medium hover:opacity-90 disabled:opacity-50 transition-opacity"
          >
            {magicForm.formState.isSubmitting ? '...' : 'Send magic link'}
          </button>
        </form>
      )}

      {import.meta.env.DEV && (
        <button
          type="button"
          onClick={async () => {
            await ensureDevSuperadminSession()
            navigate(from, { replace: true })
          }}
          className="w-full mt-3 border border-dashed border-border rounded-lg py-2 text-xs text-muted-foreground hover:text-foreground hover:border-accent transition-colors"
        >
          Dev: sign in as super_admin
        </button>
      )}

      <p className="text-center text-xs text-muted-foreground mt-4">
        {t('dontHaveAccount')}{' '}
        <Link to="/auth/signup" className="text-accent hover:underline">
          {t('signup')}
        </Link>
      </p>
    </div>
  )
}
